package cn.zj.zjmarket.domain.order.model.valobj;
import cn.zj.zjmarket.domain.order.model.entity.MarketOrder;
import java.util.Objects;
public record CloseEvidence(String outTradeNo,String orderId,String teamId,String orderStatus,String closedAt,String recordVersion,String teamVersion) {
 public void validate(MarketOrder o){if(!o.orderId().equals(outTradeNo)||!"CANCELLED".equals(orderStatus))throw new IllegalArgumentException("Invalid close association");ReservationEvidence.version(recordVersion);ReservationEvidence.instant(closedAt);if(orderId==null){if(teamId!=null||teamVersion!=null||o.evidence()!=null&&!"CLOSE_MARKER".equals(o.evidence().recordKind()))throw new IllegalArgumentException("Invalid close marker");}else{PurchaseConditions.id(orderId);PurchaseConditions.id(teamId);ReservationEvidence.version(teamVersion);var prior=o.evidence();if(prior!=null&&(!Objects.equals(prior.orderId(),orderId)||!Objects.equals(prior.teamId(),teamId)||ReservationEvidence.version(recordVersion)<ReservationEvidence.version(prior.recordVersion())||ReservationEvidence.version(teamVersion)<ReservationEvidence.version(prior.teamVersion())))throw new IllegalArgumentException("Invalid close version");if("JOIN".equals(o.confirmation().conditions().mode())&&!Objects.equals(teamId,o.confirmation().conditions().teamId()))throw new IllegalArgumentException("Invalid close team");}}
 public void validateQuery(ReservationEvidence r){if(!Objects.equals(outTradeNo,r.outTradeNo())||!Objects.equals(orderId,r.orderId())||!Objects.equals(teamId,r.teamId())||!"CANCELLED".equals(r.orderStatus())||!Objects.equals(closedAt,r.closedAt())||ReservationEvidence.version(r.recordVersion())<ReservationEvidence.version(recordVersion)||teamVersion!=null&&(r.teamVersion()==null||ReservationEvidence.version(r.teamVersion())<ReservationEvidence.version(teamVersion)))throw new IllegalArgumentException("Close and query disagree");}
}
